const { MinPriorityQueue } = require("@datastructures-js/priority-queue");
const input = require("fs").readFileSync(0, "utf8");
const cars = input.trim().split("\n").map((line) => line.trim().split(/\s+/).map(Number));

cars.sort((a, b) => a[0] - b[0]);
const done = new MinPriorityQueue();
for (const [arrive, minutes] of cars) {
  if (!done.isEmpty() && done.front() <= arrive) {
    done.dequeue();
  }
  done.enqueue(arrive + minutes);
}
console.log(`Chargers: ${done.size()}`);
